 OR (NEW.record_key GLOB 'knowledge-encoding-chunk:*' AND (NEW.kind IS NOT 'command' OR NEW.native_namespace IS NOT NULL OR NEW.native_request IS NOT NULL OR NEW.version IS NOT 1 OR json_type(CAST(NEW.payload AS TEXT), '$.knowledge_chunk_encoding') IS NOT 'text' OR json_extract(CAST(NEW.payload AS TEXT), '$.knowledge_chunk_encoding') IS NOT 'label_atoms_v1' OR (json_extract(CAST(NEW.payload AS TEXT), '$.owner.kind') IS NOT 'journal' AND json_extract(CAST(NEW.payload AS TEXT), '$.owner.kind') IS NOT 'restore') OR (json_extract(CAST(NEW.payload AS TEXT), '$.owner.kind') IS 'journal' AND (json_type(CAST(NEW.payload AS TEXT), '$') IS NOT 'object' OR json_type(CAST(NEW.payload AS TEXT), '$.knowledge_chunk_encoding') IS NOT 'text' OR json_extract(CAST(NEW.payload AS TEXT), '$.knowledge_chunk_encoding') IS NOT 'label_atoms_v1' OR json_type(CAST(NEW.payload AS TEXT), '$.owner') IS NOT 'object' OR json_type(CAST(NEW.payload AS TEXT), '$.owner.kind') IS NOT 'text' OR json_extract(CAST(NEW.payload AS TEXT), '$.owner.kind') IS NOT 'journal' OR json_type(CAST(NEW.payload AS TEXT), '$.owner.scope') IS NOT 'object' OR json_type(CAST(NEW.payload AS TEXT), '$.owner.release') IS NOT 'text' OR length(json_extract(CAST(NEW.payload AS TEXT), '$.owner.release')) NOT BETWEEN 1 AND 128 OR json_type(CAST(NEW.payload AS TEXT), '$.body_digest') IS NOT 'text' OR length(json_extract(CAST(NEW.payload AS TEXT), '$.body_digest')) IS NOT 64 OR json_extract(CAST(NEW.payload AS TEXT), '$.body_digest') GLOB '*[^0-9a-f]*' OR json_type(CAST(NEW.payload AS TEXT), '$.body_bytes') IS NOT 'integer' OR json_extract(CAST(NEW.payload AS TEXT), '$.body_bytes') NOT BETWEEN 262145 AND 192826368 OR json_type(CAST(NEW.payload AS TEXT), '$.chunk_count') IS NOT 'integer' OR json_extract(CAST(NEW.payload AS TEXT), '$.chunk_count') NOT BETWEEN 1 AND 2943 OR json_extract(CAST(NEW.payload AS TEXT), '$.chunk_count') IS NOT ((json_extract(CAST(NEW.payload AS TEXT), '$.body_bytes') + 65535) / 65536) OR json_type(CAST(NEW.pa