.owner.record_key') NOT GLOB ('knowledge-restore:' || NEW.scope_key || ':*') AND json_extract(CAST(NEW.payload AS TEXT), '$.owner.record_key') NOT GLOB ('knowledge-restore:v2:' || NEW.scope_key || ':*')))) OR json_type(CAST(NEW.payload AS TEXT), '$.ordinal') IS NOT 'integer' OR json_extract(CAST(NEW.payload AS TEXT), '$.ordinal') < 0 OR json_extract(CAST(NEW.payload AS TEXT), '$.ordinal') >= json_extract(CAST(NEW.payload AS TEXT), '$.chunk_count') OR json_type(CAST(NEW.payload AS TEXT), '$.data') IS NOT 'text' OR json_extract(CAST(NEW.payload AS TEXT), '$.data') GLOB '*[^0-9a-f]*' OR length(json_extract(CAST(NEW.payload AS TEXT), '$.data')) NOT BETWEEN 2 AND 131072 OR length(json_extract(CAST(NEW.payload AS TEXT), '$.data')) IS NOT 2 * min(65536, json_extract(CAST(NEW.payload AS TEXT), '$.body_bytes') - 65536 * json_extract(CAST(NEW.payload AS TEXT), '$.ordinal')) OR length(NEW.record_key) IS NOT 159 OR substr(NEW.record_key,26,64) GLOB '*[^0-9a-f]*' OR substr(NEW.record_key,90,1) IS NOT ':' OR substr(NEW.record_key,91,64) IS NOT json_extract(CAST(NEW.payload AS TEXT), '$.body_digest') OR substr(NEW.record_key,155,1) IS NOT ':' OR substr(NEW.record_key,156,4) IS NOT printf('%04d', json_extract(CAST(NEW.payload AS TEXT), '$.ordinal'))))
